// xLyra plugin API v1 (apiVersion 1, hostApi 2).
// Code generated by `go generate ./cmd/xlyra-plugin`; DO NOT EDIT.
// Import with `import type`; the bundle must not contain imports.

// ---- quota_probe ----

export interface ProbeContext {
  siteType: string;
  baseURL: string;
  credentialType: string;
  /** Unix time in milliseconds. */
  now: number;
  /** Non-secret account fields for per-account model sync. Includes the resolved region id when the credential does not store region. Omitted for API-key calls. */
  account?: Record<string, string>;
  /** Resolved admin settings when manifest declares settings. */
  settings?: Record<string, SettingValue>;
}

export type ProbeMethod = "DELETE" | "GET" | "PATCH" | "POST" | "PUT";

export type ProbeEndpoint = "control" | "gateway";

export interface ProbeRequest {
  method: ProbeMethod;
  /** Path under the site base URL. Absolute URLs are rejected. */
  path: string;
  headers?: Record<string, string>;
  query?: Record<string, string>;
  body?: Json;
  /** Account-pool hooks. pending on pollLogin treats a non-JSON body as still waiting. pending elsewhere, and ignore, return the status with an empty body. */
  onNonJSON?: string;
  /** Account-pool hooks only. Selects regions[].endpoints.gateway[0] instead of control. Defaults to "control". */
  endpoint?: ProbeEndpoint;
  /** Account-pool hooks only. Runs the plugin's signRequest on the outgoing request after {{secret.*}} substitution. Requires "secret.use" when credentials are needed. */
  sign?: boolean;
}

export interface ProbeResponse {
  status: number;
  headers: Record<string, string>;
  body: string;
  /** Parsed body, or null when the body is not JSON. */
  json: any;
  error?: string;
}

export interface ProbeStep {
  request: ProbeRequest;
  response: ProbeResponse;
}

export type ProbeEntryKind = "balance" | "window" | "package";

export interface ProbeEntry {
  label: string;
  kind?: ProbeEntryKind;
  name?: string;
  unit?: string;
  remaining?: number;
  limit?: number;
  used?: number;
  unlimited?: boolean;
  resetAt?: string;
  expiresAt?: string;
  cashBalance?: number;
  voucherBalance?: number;
  grantedBalance?: number;
  toppedUpBalance?: number;
}

export interface ProbeResult {
  kind: string;
  plan?: string;
  expiresAt?: string;
  isAvailable?: boolean;
  entries: ProbeEntry[];
}

// ---- model_list ----

export interface ModelListEntry {
  /** Upstream model name, as clients must send it. */
  name: string;
  displayName?: string;
  capabilities?: JsonObject;
  meta?: JsonObject;
}

export interface ModelListResult {
  models: ModelListEntry[];
}

// ---- credential_check ----

export type CredentialStatus = "ok" | "invalid" | "unavailable";

export interface CredentialCheckResult {
  /** ok: the key works. invalid: the key is rejected. unavailable: the site could not answer, so the key is unknown. */
  status: CredentialStatus;
  message?: string;
}

// ---- site_detect ----

export interface DetectContext {
  baseURL: string;
  /** Unix time in milliseconds. */
  now: number;
  /** Resolved admin settings when manifest declares settings. */
  settings?: Record<string, SettingValue>;
}

export interface SiteDetectResult {
  matched: boolean;
  /** Required when matched: which xLyra site type this site is, such as newapi. It must be a type xLyra already supports. */
  siteType?: string;
  /** 0 to 1. */
  confidence?: number;
  features?: JsonObject;
}

// ---- protocol ----

export interface ProtocolEndpointContext {
  downstreamPath: string;
  /** Resolved admin settings when manifest declares settings. */
  settings?: Record<string, SettingValue>;
}

export interface ProtocolCandidateContext {
  siteType: string;
  baseURL: string;
  upstreamName: string;
  upstreamModel: string;
}

export interface ProtocolBuildContext {
  candidate: ProtocolCandidateContext;
  /** Resolved admin settings when manifest declares settings. */
  settings?: Record<string, SettingValue>;
  /** Upstream model name. */
  model?: string;
  stream?: boolean;
  /** Canonical protocol name. */
  protocol?: string;
  /** Unix time in milliseconds. */
  now?: number;
  /** HMAC of the conversation hint, scoped to this site and plugin. Empty when no hint exists. */
  sessionKey?: string;
  /** Model meta from the site model capabilities. */
  modelMeta?: JsonObject;
  /** Plain credential, only when the plugin declares secret.use and only inside signRequest. */
  credential?: Record<string, string>;
}

export interface ProtocolBuiltRequest {
  path: string;
  headers?: Record<string, string>;
  payload: Record<string, any>;
}

export interface ProtocolResponse {
  status: number;
  headers: Record<string, string>;
  body: string;
  json: any;
}

export interface ProtocolUsage {
  prompt_tokens?: number;
  completion_tokens?: number;
  total_tokens?: number;
}

export interface ProtocolSignInput {
  method: string;
  /** Full upstream URL including the query string. */
  url: string;
  /** Headers about to be sent, without credentials. */
  headers: Record<string, string>;
  /** The exact request body that will be sent (at most 16 MiB). */
  body: string;
}

export interface ProtocolSignResult {
  /** sign asks Go to HMAC stringToSign. rewrite applies headers, query, and body directly. */
  mode: SignRequestMode;
  /** The exact text to sign. At most 64 KiB. Required in sign mode. */
  stringToSign?: string;
  algorithm?: SignAlgorithm;
  /** Defaults to hex. */
  encoding?: SignEncoding;
  /** Header that carries the signature, such as Authorization or X-Signature. */
  header?: string;
  /** Text put before the encoded signature, such as 'HMAC-SHA256 '. */
  prefix?: string;
  /** Extra non-secret headers to send, such as a timestamp or nonce. */
  headers?: Record<string, string>;
  /** Query parameters to set on the upstream URL. Rewrite mode only. */
  query?: Record<string, string>;
  /** Replaces the whole upstream body. At most 16 MiB. Rewrite mode only. */
  body?: string;
}

export interface ProtocolErrorResult {
  contentType?: string;
  /** The error body returned to the client. */
  body: string;
}

// ---- error_classifier ----

export type FailureClass = "unknown" | "limited" | "subscription_limit" | "transient" | "credential_invalid";

export interface ErrorClassifyContext {
  siteType: string;
  /** Resolved admin settings when manifest declares settings. */
  settings?: Record<string, SettingValue>;
}

export interface ErrorClassifyInput {
  status: number;
  /** Error code from the upstream body, if any. */
  code?: string;
  /** Error type from the upstream body, if any. */
  type?: string;
  /** Error message, cut to 1024 bytes. */
  message?: string;
}

export interface ErrorClassifyResult {
  class: FailureClass;
  /** Short note for logs, at most 200 bytes. */
  reason?: string;
}

