export interface RewritePayloadContext {
  siteType: string;
  /** Upstream model name. */
  model: string;
  stream: boolean;
  /** Canonical protocol name, such as openai_chat. */
  protocol: string;
  /** Resolved admin settings when manifest declares settings. */
  settings?: Record<string, SettingValue>;
}

export interface AccountLoginContext {
  siteType: string;
  baseURL: string;
  /** Login parameters from the admin UI. Not credentials. */
  params: Record<string, string>;
  /** Unix time in milliseconds. */
  now: number;
  /** Resolved admin settings when manifest declares settings. */
  settings?: Record<string, SettingValue>;
}

export type AccountLoginStatus = "pending" | "complete";

export interface AccountLoginResult {
  /** Must be account_login. */
  kind: string;
  status: AccountLoginStatus;
  verificationURL?: string;
  userCode?: string;
  interval?: number;
  /** Secret fields are {{secret.<field>}} bag references. Non-secret fields are plain strings. Token values are rejected. */
  credential?: Record<string, string>;
}

export interface AccountCredentialContext {
  siteType: string;
  baseURL: string;
  /** Non-secret credential fields only. Access tokens and other secrets are omitted. */
  fields: Record<string, string>;
  /** Unix time in milliseconds. */
  now: number;
  /** Resolved admin settings when manifest declares settings. */
  settings?: Record<string, SettingValue>;
}

export type AccountRefreshStatus = "ok" | "reauth";

export interface AccountRefreshResult {
  /** Must be account_refresh. */
  kind: string;
  status: AccountRefreshStatus;
  /** Secret fields are {{secret.<field>}} bag references. Non-secret fields are plain strings. Token values are rejected. */
  credential?: Record<string, string>;
}

export type AccountSummaryStatus = "ok" | "unavailable" | "reauth";

export interface AccountSummaryResult {
  /** Must be account_summary. */
  kind: string;
  status: AccountSummaryStatus;
  remark?: string;
  /** Display text. Stored only when credential.display lists summary.label. */
  label?: string;
  entries: ProbeEntry[];
}

export interface TransportProfile {
  /** Built-in TLS fingerprint. */
  profile?: "claude_code" | "bun";
}

// ---- stream ----

export interface StreamUnwrap {
  /** Dot path with numeric indexes, same syntax as secretPaths. */
  path: string;
  /** json reads an object or array. json_string parses a JSON string. raw uses the string as the payload. Default is json. */
  format?: "json" | "json_string" | "raw";
  /** Envelope status path. Checked only when okStatuses is set. */
  statusPath?: string;
  /** Allowed envelope statuses. Empty skips the check. */
  okStatuses?: number[];
}

export interface StreamDone {
  /** Original data payload equals one of these. */
  dataEquals?: string[];
  /** Unwrapped payload equals one of these. */
  unwrappedEquals?: string[];
  /** SSE event name equals one of these. */
  events?: string[];
  /** Stop reading the upstream body after a done marker. */
  closeOnDone?: boolean;
}

export interface StreamUsage {
  /** Copied to usage.prompt_tokens when that field is absent. */
  inputTokens?: string;
  /** Copied to usage.completion_tokens when that field is absent. */
  outputTokens?: string;
  /** Copied to usage.prompt_tokens_details.cached_tokens when that field is absent. */
  cachedTokens?: string;
  /** Copied to usage.completion_tokens_details.reasoning_tokens when that field is absent. */
  reasoningTokens?: string;
}

export interface StreamSection {
  unwrap?: StreamUnwrap;
  done?: StreamDone;
  usage?: StreamUsage;
}

export interface StreamTransformContext {
  siteType?: string;
  model?: string;
  protocol?: string;
  settings?: Record<string, SettingValue>;
}

export interface StreamTransformEvent {
  event?: string;
  data: string;
}

export interface StreamTransformResult {
  event?: string;
  data?: string;
  drop?: boolean;
  done?: boolean;
}

// ---- schedule ----

export interface ScheduleContext {
  siteType?: string;
  baseURL?: string;
  /** Non-secret account fields when running for an account pool. */
  fields?: Record<string, string>;
  account?: Record<string, string>;
  /** Unix time in milliseconds. */
  now: number;
  /** Resolved admin settings when manifest declares settings. */
  settings?: Record<string, SettingValue>;
}

export interface ScheduleSection {
  /** Interval in minutes (5..10080) between onSchedule ticks. */
  everyMinutes?: number;
  /** Localized label shown in the admin schedule toggle. */
  label?: Record<string, string>;
}

export type PluginKind = "quota_probe" | "protocol" | "model_list" | "credential_check" | "site_detect" | "error_classifier" | "model_metadata" | "pricing_parse" | "automation" | "site_provider";

export interface PluginManifest {
  apiVersion: number;
  hostApi: number;
  id: string;
  name: string;
  version: string;
  kind?: PluginKind;
  exports?: string[];
  transport?: TransportProfile;
  /** Declarative SSE transform. On a protocol plugin this is protocol.stream. On a site type it is siteProvider.protocol.stream. */
  stream?: StreamSection;
  /** Periodic onSchedule configuration. Requires schedule in permissions. */
  schedule?: ScheduleSection;
}

export interface PluginMeta {
  apiVersion: number;
  id: string;
  kind?: PluginKind;
}

export type Json = null | boolean | number | string | Json[] | { [key: string]: Json };
export type JsonObject = Record<string, Json>;
export type SettingValue = string | number | boolean;
export type BinaryLike = string | Uint8Array;
export type DigestAlgorithm = "md5" | "sha1" | "sha256" | "sha512";
export type DigestEncoding = "hex" | "base64" | "base64url";
export type AESAlgorithm = "aes-128-gcm" | "aes-256-gcm" | "aes-128-cbc" | "aes-256-cbc";
export type RSAPadding = "oaep-sha256" | "oaep-sha1" | "pkcs1v15";

// ---- hook return values ----

/** Return exactly one of request, result, or error. */
export type ProbeDecision =
  | { request: ProbeRequest; result?: never; error?: never }
  | { result: ProbeResult; request?: never; error?: never }
  | { error: string; request?: never; result?: never };

/** Return exactly one of request, result, or error. R is the kind's result type. */
export type SteppedDecision<R> =
  | { request: ProbeRequest; result?: never; error?: never }
  | { result: R; request?: never; error?: never }
  | { error: string; request?: never; result?: never };

/** What an admin picked for one input: an object (several when the input is multiple) or a parameter value. */
export type AutomationInputValue = AutomationEntity | AutomationEntity[] | string | number | boolean;

export type ModelListDecision = SteppedDecision<ModelListResult>;
export type CredentialCheckDecision = SteppedDecision<CredentialCheckResult>;
export type SiteDetectDecision = SteppedDecision<SiteDetectResult>;
export type ScheduleDecision = SteppedDecision<JsonObject>;

export type ProtocolDecodeResult =
  | { model: string; error?: never }
  | { error: { status: number; code: string; message: string }; model?: never };

export type SignAlgorithm = "hmac-sha256" | "hmac-sha1" | "hmac-sha512";
export type SignEncoding = "hex" | "base64";
export type SignRequestMode = "sign" | "rewrite";

/** signRequest return: ask the host to sign, or rewrite the request directly. */
export type SignRequestResult =
  | {
      stringToSign: string;
      algorithm: SignAlgorithm;
      encoding?: SignEncoding;
      header: string;
      prefix?: string;
      headers?: Record<string, string>;
      query?: never;
      body?: never;
    }
  | {
      headers?: Record<string, string>;
      query?: Record<string, string>;
      body?: string;
      stringToSign?: never;
      algorithm?: never;
      encoding?: never;
      header?: never;
      prefix?: never;
    };

export interface ProtocolParsedResponse {
  /** Send the upstream body to the client unchanged. */
  passthrough?: boolean;
  status?: number;
  contentType?: string;
  body?: string;
  usage?: ProtocolUsage;
  error?: string;
}

// ---- host API v2 (globals) ----

declare global {
  const bytes: {
    fromUTF8(text: string): Uint8Array;
    toUTF8(data: Uint8Array): string;
    fromHex(hex: string): Uint8Array;
    toHex(data: Uint8Array): string;
    fromBase64(b64: string): Uint8Array;
    toBase64(data: Uint8Array): string;
    fromBase64URL(b64url: string): Uint8Array;
    toBase64URL(data: Uint8Array): string;
    concat(chunks: Uint8Array[]): Uint8Array;
    equal(a: Uint8Array, b: Uint8Array): boolean;
  };
  const encoding: {
    hexEncode(data: BinaryLike): string;
    hexDecode(hex: string): Uint8Array;
    base64Encode(data: BinaryLike): string;
    base64Decode(b64: string): Uint8Array;
    base64URLEncode(data: BinaryLike): string;
    base64URLDecode(b64url: string): Uint8Array;
    utf8Encode(text: string): Uint8Array;
    utf8Decode(data: Uint8Array): string;
  };
  const codec: {
    base64Encode(value: string): string;
    base64Decode(value: string): string;
    base64URLEncode(value: string): string;
    base64URLDecode(value: string): string;
  };
  const crypto: {
    hmacSHA256(key: string, message: string): string;
    sha256(data: BinaryLike, encoding?: DigestEncoding): string;
    md5(data: BinaryLike, encoding?: DigestEncoding): string;
    sha1(data: BinaryLike, encoding?: DigestEncoding): string;
    sha512(data: BinaryLike, encoding?: DigestEncoding): string;
    digestBytes(alg: DigestAlgorithm, data: BinaryLike): Uint8Array;
    hmac(alg: DigestAlgorithm, key: BinaryLike, data: BinaryLike, encoding?: DigestEncoding): string;
    hmacBytes(alg: DigestAlgorithm, key: BinaryLike, data: BinaryLike): Uint8Array;
    randomBytes(length: number): Uint8Array;
    aesEncrypt(alg: AESAlgorithm, key: BinaryLike, iv: BinaryLike, plaintext: BinaryLike, aad?: BinaryLike): Uint8Array;
    aesDecrypt(alg: AESAlgorithm, key: BinaryLike, iv: BinaryLike, ciphertext: BinaryLike, aad?: BinaryLike): Uint8Array;
    rsaEncrypt(publicKeyPEM: string, plaintext: BinaryLike, padding?: RSAPadding): Uint8Array;
  };
  const jwt: {
    signHS256(payload: Record<string, any>, secret: string): string;
    decodeHS256(token: string, secret: string): any;
  };
  const storage: {
    get(key: string): Json;
    set(key: string, value: Json): void;
    delete(key: string): boolean;
    keys(): string[];
  };
  const utils: { uuid(): string };
  const log: {
    debug(message: string, fields?: Record<string, any>): void;
    info(message: string, fields?: Record<string, any>): void;
    warn(message: string, fields?: Record<string, any>): void;
  };
}

// ---- site_provider hooks ----

export type SiteProviderProbe = (ctx: ProbeContext, steps: ProbeStep[]) => ProbeDecision;
export type SiteProviderListModels = (ctx: ProbeContext, steps: ProbeStep[]) => ModelListDecision;
export type SiteProviderCheck = (ctx: ProbeContext, steps: ProbeStep[]) => CredentialCheckDecision;
export type SiteProviderClassify = (ctx: ErrorClassifyContext, input: ErrorClassifyInput) => ErrorClassifyResult;
export type SiteProviderRewritePayload = (ctx: RewritePayloadContext, payload: Record<string, unknown>) => Record<string, unknown>;
export type SiteProviderTransformStream = (ctx: StreamTransformContext, event: StreamTransformEvent) => StreamTransformResult;

export type AccountLoginDecision = SteppedDecision<AccountLoginResult>;
export type AccountRefreshDecision = SteppedDecision<AccountRefreshResult>;
export type AccountSummaryDecision = SteppedDecision<AccountSummaryResult>;
export type SiteProviderStartLogin = (ctx: AccountLoginContext, steps: ProbeStep[]) => AccountLoginDecision;
export type SiteProviderPollLogin = (ctx: AccountLoginContext, steps: ProbeStep[]) => AccountLoginDecision;
export type SiteProviderRefreshTokens = (ctx: AccountCredentialContext, steps: ProbeStep[]) => AccountRefreshDecision;
export type SiteProviderSummarizeAccount = (ctx: AccountCredentialContext, steps: ProbeStep[]) => AccountSummaryDecision;
export type SiteProviderOnSchedule = (ctx: ScheduleContext, steps: ProbeStep[]) => ScheduleDecision;

export interface SiteProviderHooks {
  probe?: SiteProviderProbe;
  listModels?: SiteProviderListModels;
  check?: SiteProviderCheck;
  classify?: SiteProviderClassify;
  rewritePayload?: SiteProviderRewritePayload;
  transformStream?: SiteProviderTransformStream;
  startLogin?: SiteProviderStartLogin;
  pollLogin?: SiteProviderPollLogin;
  refreshTokens?: SiteProviderRefreshTokens;
  summarizeAccount?: SiteProviderSummarizeAccount;
  onSchedule?: SiteProviderOnSchedule;
}
